package com.vaijunto.dto;
import com.vaijunto.domain.entities.Conversation; import java.time.OffsetDateTime; import java.util.UUID;
public record ConversationDto(UUID id,String type,String title,UUID otherUserId,boolean archived,boolean readOnly,OffsetDateTime lastActivityAt) { public static ConversationDto from(Conversation c, UUID userId) { var other=c.getParticipantA()!=null&&c.getParticipantA().getId().equals(userId)?c.getParticipantB():c.getParticipantA(); String title="ADMINISTRATIVE".equals(c.getType())?adminName(c):other==null ? ("OFFICIAL".equals(c.getType())?"VaiJunto":"Atendimento") : other.getName(); return new ConversationDto(c.getId(),c.getType(),title,other==null?null:other.getId(),c.getArchivedAt()!=null,c.getReadOnlyAt()!=null||"OFFICIAL".equals(c.getType()),c.getLastActivityAt()); } private static String adminName(Conversation c){if(c.getAdminAccount()==null||c.getAdminAccount().getEmail()==null)return "VaiJunto";String email=c.getAdminAccount().getEmail();int at=email.indexOf('@');return at>0?email.substring(0,at):email;} }
